random.seed(1); data=random.randbytes(20000*1024)
def oneshot(): return hashes.Hash.hash(hashes.SHA256(), data)
def ref(): d=hashes.Hash(hashes.SHA256()); d.update(data); return d.finalize()
for _ in range(3): oneshot(); ref()
for name,fn in [('oneshot',oneshot),('ref',ref)]:
    ts=[]
    for _ in range(15):
        t0=time.perf_counter(); fn(); ts.append(time.perf_counter()-t0)
    print(name, round(statistics.median(ts),4), round(min(ts),4))
""}

